"grab-able":{title:"Grab-able glove",period:"2022—2023",phase:"Study abroad · University of Bologna",role:"Product designer",image:"page-03.jpg",gallery:["page-04.jpg","page-05.jpg"],summary:"An affordable exoskeleton glove that helps people regain hand movement after a stroke.",challenge:"Create an assistive glove that supports natural finger movement while remaining affordable and easy to put on.",story:"For Montecatone Rehabilitation Institute, I designed a glove that translates EMG activity in the upper arm into movement. A motor flexes the fingers while flexible components guide them back. Adjustable parts make the fit more personal.",outcomes:["Adjustable sizing","Interchangeable flexures","Simple to put on","Designed for a natural movement"],next:"fairground-seat"},
"fairground-seat":{title:"Fairground ride seat",period:"2021—2022",phase:"Creative engineer · 3D Next Level",role:"Product designer & CAD engineer",image:"page-06.jpg",gallery:["page-07.jpg"],summary:"An anatomical, weather-resistant seat for a fairground ride.",challenge:"Translate a bold idea into a production-ready seat that is comfortable, sheds water and works across multiple attractions.",story:"During my internship at 3D Next Level, I developed the dimensions and SolidWorks model for a seat commissioned by Henri Groels. I considered polyester manufacturing, discreet seams and drainage from the beginning.",outcomes:["Based on anatomical dimensions","Outdoor-ready design","Adaptable for several attractions"],next:"relaxi"},
"relaxi":{title:"Vegro — Relaxi",period:"2019—2023",phase:"BSc Industrial Product Design · Rotterdam UAS",role:"Interaction & product designer",image:"page-08.jpg",gallery:["page-09.jpg"],summary:"Gentle warmth and massage designed to invite older adults with dementia back into small moments of activity.",challenge:"Offer stimulating interaction without overwhelming people experiencing apathy caused by dementia.",story:"Relaxi brings massage and warmth together in an intentionally simple object. The interaction is kept calm and legible so that users can pick it up and use it independently.",outcomes:["Massage and warming functions","Low-stimulus interaction","Accessible controls"],next:"brienenoord"},
"brienenoord":{title:"Furniture for Brienenoord Island",period:"2019—2023",phase:"BSc Industrial Product Design · Rotterdam UAS",role:"Public-space designer",image:"page-12.jpg",gallery:["page-13.jpg"],summary:"A bench that transforms into a football goal in one movement.",challenge:"Invite both rest and play in a nature area, while resolving the safety details of a moving public object.",story:"For EMI in Rotterdam-Zuid, I designed a public-space intervention for Eiland van Brienenoord. Folding the bench turns it into a goal, encouraging visitors to be active without adding another separate piece of street furniture.",outcomes:["Bench and goal in one","Encourages active use","Folding mechanism considers pinch safety"],next:"guitar"},
"guitar":{title:"Guitar building",period:"Personal project",phase:"Making as a practice",role:"Designer & maker",image:"page-14.jpg",gallery:["page-15.jpg"],summary:"A self-built guitar bringing together precision, woodwork and personal detail.",challenge:"Make an instrument from the ground up—and give its construction a distinctive personal character.",story:"From bending wood and routing parts to working accurately on the frets, this project was an exercise in patience. It includes a custom rosette, pickguard, a laser-engraved plate and a neck engraving based on my own sketch.",outcomes:["Build plan, routing and wood bending","Custom neck engraving","Personalised finishing details"],next:"grab-able"}
